const body = $input.first().json.body ?? $input.first().json;
const action = body.action ?? '';
const clientId = body.client_id ?? '';
const orgId = body.org_id ?? '';
const valid = ['test_connection','apply_schema','create_user','reset_password','invite_user'];
if (!valid.includes(action)) throw new Error(`Ação inválida: ${action}`);
if (!clientId) throw new Error('client_id é obrigatório');
return [{ json: { action, client_id: clientId, org_id: orgId, payload: body } }];

const creds = $input.first().json;
const prev = $('Validar Payload').first().json;
if (!creds.success) throw new Error(creds.error ?? 'Credenciais não encontradas para este cliente');
if (!creds.supabase_url) throw new Error('URL do banco de dados do cliente não configurada');
const needsServiceKey = ['apply_schema','create_user','reset_password','invite_user'];
if (needsServiceKey.includes(prev.action) && !creds.service_key) {
  throw new Error('Service Key do cliente não configurada — preencha na aba Banco de Dados do cliente no C8 Control');
}
return [{ json: { action: prev.action, client_id: prev.client_id, payload: prev.payload, supabase_url: creds.supabase_url, anon_key: creds.anon_key, service_key: creds.service_key } }];

const prev = $('Validar e Combinar Credenciais').first().json;
const schemaText = $input.first().json?.data ?? $input.first().json ?? '';
return [{ json: { ...prev, schema_sql: String(schemaText) } }];

const { action, supabase_url, anon_key, service_key, payload, schema_sql } = $input.first().json;
const base = supabase_url.replace(/\/$/, '');
let result;

// Geração de senha segura — mesmo algoritmo das Edge Functions c8-provision-tenant e c8-reset-password.
// Usa crypto.getRandomValues (disponível no n8n) para evitar Math.random() (inseguro e inconsistente).
// Formato: xxxx-xxxx-xxxx (sem caracteres ambíguos 0/O, 1/l/I)
function generateTempPassword() {
  const chars = 'abcdefghjkmnpqrstuvwxyz23456789';
  const groups = 3, groupLen = 4;
  let pwd = '';
  const bytes = new Uint8Array(groups * groupLen);
  crypto.getRandomValues(bytes);
  for (let g = 0; g < groups; g++) {
    if (g > 0) pwd += '-';
    for (let i = 0; i < groupLen; i++) pwd += chars[bytes[g * groupLen + i] % chars.length];
  }
  return pwd;
}

if (action === 'test_connection') {
  const res = await fetch(`${base}/rest/v1/schema_migrations?select=version&limit=1`, {
    headers: { apikey: anon_key, Authorization: `Bearer ${anon_key}` },
  });
  if (res.ok) result = { success: true, schema_applied: true, message: 'Banco conectado e schema aplicado.' };
  else if (res.status === 404) result = { success: true, schema_applied: false, message: 'Banco conectado, schema ainda não aplicado.' };
  else if (res.status === 401) result = { success: false, error: 'Anon Key inválida.' };
  else result = { success: false, error: `HTTP ${res.status}` };

} else if (action === 'apply_schema') {
  // Delega para a Edge Function provision-client-db, que:
  //   1. Faz bootstrap do exec_sql via /pg/query se banco zerado
  //   2. Aplica o schema completo (BANK_B_FULL_SCHEMA inline na Edge Function)
  //   3. Faz seed dos estágios do pipeline
  // Não depende mais de buscar o schema do GitHub.
  const supabaseAUrl = $env.SUPABASE_URL.replace(/\/$/, '');
  const serviceKey   = $env.SUPABASE_SERVICE_KEY;
  const res = await fetch(`${supabaseAUrl}/functions/v1/provision-client-db`, {
    method: 'POST',
    headers: {
      'Content-Type':  'application/json',
      'apikey':        serviceKey,
      'Authorization': `Bearer ${serviceKey}`,
    },
    body: JSON.stringify({ client_id: payload.client_id }),
  });
  const data = await res.json().catch(() => ({}));
  if (res.ok && data.success) {
    // Grava timestamp no Banco A — silencia erros para não bloquear o resultado
    try {
      await fetch(`${supabaseAUrl}/rest/v1/rpc/update_c8_schema_timestamp`, {
        method: 'POST',
        headers: {
          'Content-Type':  'application/json',
          'apikey':        serviceKey,
          'Authorization': `Bearer ${serviceKey}`,
        },
        body: JSON.stringify({ p_client_id: payload.client_id }),
      });
    } catch (_) {}
    result = { success: true,  message: data.message ?? 'Schema aplicado com sucesso.' };
  } else {
    result = { success: false, error: data.error ?? `HTTP ${res.status}` };
  }

} else if (action === 'create_user') {
  // Usa generateTempPassword — mesmo algoritmo das Edge Functions.
  // A senha gerada aqui É a senha registrada no Banco B — sem discrepância.
  const email = payload.email;
  if (!email?.includes('@')) throw new Error('E-mail inválido para create_user');
  const tempPass = generateTempPassword();
  const expiresAt = new Date(Date.now() + 72 * 60 * 60 * 1000).toISOString();
  const res = await fetch(`${base}/auth/v1/admin/users`, {
    method: 'POST',
    headers: { apikey: service_key, Authorization: `Bearer ${service_key}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      email,
      password: tempPass,
      email_confirm: true,
      user_metadata: {
        client_id: payload.client_id,
        role: 'owner',
        full_name: payload.client_name ?? '',
        force_password_change: true,
        temp_password_expires_at: expiresAt,
      },
    }),
  });
  const data = await res.json().catch(() => ({}));
  result = res.ok
    ? { success: true, user_id: data.id, temp_password: tempPass,
        message: `Usuário criado: ${email}. Senha válida por 72h.` }
    : { success: false, error: data.message ?? data.error_description ?? `HTTP ${res.status}` };

} else if (action === 'reset_password') {
  // Gera nova senha temporária com o mesmo algoritmo das Edge Functions.
  // Localiza o usuário no Banco B e atualiza a senha diretamente — sem link de recovery.
  // Retorna temp_password para o frontend exibir/enviar ao cliente.
  const email = payload.email;
  if (!email?.includes('@')) throw new Error('E-mail inválido para reset_password');
  const tempPass = generateTempPassword();
  const expiresAt = new Date(Date.now() + 72 * 60 * 60 * 1000).toISOString();

  // Localiza o usuário pelo e-mail
  const listRes = await fetch(`${base}/auth/v1/admin/users?per_page=1000`, {
    headers: { apikey: service_key, Authorization: `Bearer ${service_key}` },
  });
  const listData = await listRes.json().catch(() => ({ users: [] }));
  const existing = (listData.users ?? []).find(
    (u) => u.email?.toLowerCase() === email.toLowerCase()
  );

  if (existing) {
    // Usuário existe — atualiza senha e renova prazo de 72h
    const updateRes = await fetch(`${base}/auth/v1/admin/users/${existing.id}`, {
      method: 'PUT',
      headers: { apikey: service_key, Authorization: `Bearer ${service_key}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        password: tempPass,
        ban_duration: 'none',
        user_metadata: {
          ...existing.user_metadata,
          force_password_change: true,
          temp_password_expires_at: expiresAt,
        },
      }),
    });
    result = updateRes.ok
      ? { success: true, is_new_user: false, temp_password: tempPass,
          message: `Senha redefinida para ${email}. Válida por 72h.` }
      : { success: false, error: `Erro ao atualizar senha: HTTP ${updateRes.status}` };
  } else {
    // Usuário não existe — cria novo
    const createRes = await fetch(`${base}/auth/v1/admin/users`, {
      method: 'POST',
      headers: { apikey: service_key, Authorization: `Bearer ${service_key}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        email,
        password: tempPass,
        email_confirm: true,
        user_metadata: {
          client_id: payload.client_id,
          role: 'owner',
          force_password_change: true,
          temp_password_expires_at: expiresAt,
        },
      }),
    });
    const createData = await createRes.json().catch(() => ({}));
    result = createRes.ok
      ? { success: true, is_new_user: true, temp_password: tempPass,
          message: `Usuário criado e senha gerada para ${email}. Válida por 72h.` }
      : { success: false, error: createData.message ?? `HTTP ${createRes.status}` };
  }

} else if (action === 'invite_user') {
  const email = payload.email;
  const role = payload.role ?? 'member';
  const res = await fetch(`${base}/auth/v1/admin/invite`, {
    method: 'POST',
    headers: { apikey: service_key, Authorization: `Bearer ${service_key}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ email, data: { client_id: payload.client_id, role } }),
  });
  const data = await res.json().catch(() => ({}));
  result = res.ok
    ? { success: true, message: `Convite enviado para ${email} com role ${role}` }
    : { success: false, error: data.message ?? data.error_description ?? `HTTP ${res.status}` };
}

return [{ json: { ...result, action } }];
